package textnorm

// foldCJKForFingerprint 将常见繁体汉字按一对一规则折叠为对应简体码点，仅用于去重指纹与标题分词，不改写展示文本。
// 仅处理 BMP 常见汉字区间（U+3400..U+9FFF）；表内映射均收敛为单步不动点（fold(fold(r)) == fold(r)）。
func foldCJKForFingerprint(r rune) rune {
	if r < 0x3400 || r > 0x9FFF {
		return r
	}
	key := uint16(r)
	lo, hi := 0, len(cjkTradToSimpTable)
	for lo < hi {
		mid := int(uint(lo+hi) >> 1)
		cur := uint16(cjkTradToSimpTable[mid] >> 16)
		if cur < key {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo < len(cjkTradToSimpTable) && uint16(cjkTradToSimpTable[lo]>>16) == key {
		return rune(cjkTradToSimpTable[lo] & 0xFFFF)
	}
	return r
}

